import numpy as np
from sklearn.metrics import roc_auc_score


# Define the model architecture based on iteration number
def create_model(iteration):
    if iteration % 3 == 0:
        num_conv_layers = 2
        dropout_rate = 0.0
    elif iteration % 3 == 1:
        num_conv_layers = 3
        dropout_rate = 0.2
    else:
        num_conv_layers = 4
        dropout_rate = 0.5

    conv_layers = []
    in_channels = 1
    for i in range(num_conv_layers):
        out_channels = 32 * (i + 1)
        conv_layers.extend([
            nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1),
            nn.BatchNorm2d(out_channels),
            nn.ReLU(),
            nn.MaxPool2d(kernel_size=2, stride=2)
        ])
        in_channels = out_channels

    model = nn.Sequential(
        *conv_layers,
        nn.AdaptiveAvgPool2d((1, 1)),
        nn.Flatten(),
        nn.Linear(in_channels, 128),
        nn.ReLU(),
        nn.Dropout(dropout_rate),
        nn.Linear(128, 234)
    )
    return model

# Set up data loader
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
iteration = 14  # Current iteration number
batch_size_options = [8, 16, 32]
lr_options = [0.001, 0.0001, 0.00001]

batch_size = batch_size_options[iteration % 3]
lr = lr_options[iteration % 3]
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

# Create model and move to GPU
model = create_model(iteration)
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model.to(device)

# Define loss function and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=0.001)

# Training loop
num_epochs = 2
batch_count = 0
training_samples = 0
eval_samples = 80  # Number of samples for validation

model.train()
for epoch in range(num_epochs):
    running_loss = 0.0
    for inputs, labels in train_loader:
        if batch_count >= 10:  # Limit to first ~5000 samples (~10 batches)
            break
        
        optimizer.zero_grad()
        
        inputs, labels = inputs.to(device), labels.to(device)
        outputs = model(inputs)
        loss = criterion(outputs, labels.float())
        loss.backward()
        optimizer.step()
        
        running_loss += loss.item()
        training_samples += inputs.size(0)
        
        print(f'Epoch {epoch+1}/{num_epochs}, Batch {batch_count+1}, Loss: {loss.item():.4f}')
        
        torch.cuda.empty_cache()  # Prevent GPU fragmentation
        batch_count += 1

# Evaluation loop
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in train_loader:
        if eval_samples <= 0:
            break
        
        inputs, labels = inputs.to(device), labels.to(device)
        outputs = model(inputs)
        all_preds.append(outputs.sigmoid().cpu().numpy())
        all_labels.append(labels.cpu().numpy())
        eval_samples -= inputs.size(0)

all_preds = np.concatenate(all_preds)
all_labels = np.concatenate(all_labels)

# Compute validation AUC
final_auc = roc_auc_score(all_labels, all_preds, average='weighted')

# Save metrics
num_params = sum(p.numel() for p in model.parameters())
metrics = {
    "final_train_loss": running_loss / batch_count,
    "final_auc": final_auc,
    "num_params": num_params,
    "epochs_trained": num_epochs,
    "batch_size": batch_size,
    "training_samples": training_samples,
    "eval_samples": 80 - eval_samples
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

# Save model checkpoint
